ns16:scriptTask.ns16:script:
tw.local.odcRequest.stepLog ={};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step      =  tw.epv.ScreenNames.closureACT06;
tw.local.odcRequest.appInfo.stepName = tw.epv.ScreenNames.closureACT06;
tw.local.actionConditions = {};
tw.local.actionConditions.screenName     = tw.epv.ScreenNames.closureACT06;
tw.local.actionConditions.lastStepAction = tw.local.lastAction;
if(tw.local.statues!="Success" && !!tw.local.statues)
{

	tw.local.RPAmassage = "Failed RPA with message : " + tw.local.ErrorMassageRPA;
	tw.local.RPAvis = "Readonly";
}
else{
	tw.local.RPAvis = "none";
}

 tw.local.errorMessage ="";
 var mandatoryTriggered = false;
 
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToMaker || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator )
	{
		mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
		maxLength(tw.local.odcRequest.stepLog.returnReason , "tw.local.odcRequest.stepLog.returnReason", 80 , "Shouldn't be more than 80 character" , "Return reason: " + "Shouldn't be more than 80 character" );
	}

function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{			
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
	
			default:
				
				// VALIDATE DATE OBJECT
				if( field && field.getTime && isFinite(field.getTime()) ) {}
				
				else
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;	
				}
		}
	}
	return true;
}

function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}
function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}
maxLength(tw.local.odcRequest.stepLog.comment , "tw.local.odcRequest.stepLog.comment", 500 , "Shouldn't be more than 500 character" , "Comment: " + "Shouldn't be more than 500 character" );
 tw.local.errorMessage ="";

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest)
{
	tw.local.odcRequest.appInfo.status    ="" + tw.epv.Status.completed;
	tw.local.odcRequest.appInfo.subStatus ="" + tw.epv.Status.completed;
	
	tw.local.odcRequest.BasicDetails.requestState = "Closed";
}
if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToMaker)
{
	tw.local.odcRequest.appInfo.status    ="" + tw.epv.Status.InExecution;
	tw.local.odcRequest.appInfo.subStatus ="" + tw.epv.Status.pendingExecutionHubClosure;
	
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.initiated;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.returnToInitiator;
}
if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo)
{
	tw.local.odcRequest.appInfo.status    =""+ tw.epv.Status.InApproval;
	tw.local.odcRequest.appInfo.subStatus ="" + tw.epv.Status.awaitingTradeFOApproval;

}

tw.local.odcRequest.stepLog.role     = "Hub checker";
tw.local.odcRequest.stepLog.userName = tw.system.user.name;
tw.local.odcRequest.stepLog.endTime  = new Date();
tw.local.odcRequest.History.push(tw.local.odcRequest.stepLog);

